   110→/// Find the tspec for a crate - tries as path first, then relative to crate_dir
   111→/// Returns None if no tspec exists (plain cargo build will be used)
   112→pub fn find_tspec(crate_dir: &Path, explicit: Option<&str>) -> Result<Option<PathBuf>> {
   113→    match explicit {
   114→        Some(name) => {
   115→            // Try as path first (relative to cwd or absolute)
   116→            let as_path = PathBuf::from(name);
   117→            if as_path.exists() {
   118→                return Ok(Some(as_path.canonicalize().unwrap_or(as_path)));
   119→            }
   120→
   121→            // Fallback: relative to crate directory
   122→            let in_crate = crate_dir.join(name);
   123→            if in_crate.exists() {
   124→                return Ok(Some(in_crate));
   125→            }
   126→
   127→            // Try with TSPEC_SUFFIX if name has no extension
   128→            if !name.contains('.') {
   129→                let with_suffix = crate_dir.join(format!("{}{}", name, TSPEC_SUFFIX));
   130→                if with_suffix.exists() {
   131→                    return Ok(Some(with_suffix));
   132→                }
   133→            }
   134→
   135→            bail!("tspec not found: {}", name);
   136→        }
   137→        None => {
   138→            let default = crate_dir.join(format!("tspec{}", TSPEC_SUFFIX));
   139→            if default.exists() {
   140→                Ok(Some(default))
   141→            } else {
   142→                Ok(None) // No tspec = plain cargo build
   143→            }
   144→        }
   145→    }
   146→}
