   148→/// Find multiple tspecs by glob patterns
   149→/// If no patterns given, defaults to "tspec*{TSPEC_SUFFIX}"
   150→/// Returns sorted list of paths, errors if none found
   151→pub fn find_tspecs(crate_dir: &Path, patterns: &[String]) -> Result<Vec<PathBuf>> {
   152→    let default_pattern = format!("tspec*{}", TSPEC_SUFFIX);
   153→    let patterns: Vec<&str> = if patterns.is_empty() {
   154→        vec![&default_pattern]
   155→    } else {
   156→        patterns.iter().map(|s| s.as_str()).collect()
   157→    };
   158→
   159→    let mut results = Vec::new();
   160→
   161→    for pattern in &patterns {
   162→        // Try as literal path first (relative to cwd or absolute)
   163→        let as_path = PathBuf::from(pattern);
   164→        if as_path.exists() && as_path.is_file() {
   165→            results.push(as_path.canonicalize().unwrap_or(as_path));
   166→            continue;
   167→        }
   168→
   169→        // Try as literal path relative to crate_dir
   170→        let in_crate = crate_dir.join(pattern);
   171→        if in_crate.exists() && in_crate.is_file() {
   172→            results.push(in_crate);
   173→            continue;
   174→        }
   175→
   176→        // Try as glob pattern in crate_dir
   177→        let glob_pattern =
   178→            Pattern::new(pattern).with_context(|| format!("invalid glob pattern: {}", pattern))?;
   179→
   180→        let entries: Vec<_> = std::fs::read_dir(crate_dir)
   181→            .with_context(|| format!("cannot read directory: {}", crate_dir.display()))?
   182→            .filter_map(|e| e.ok())
   183→            .filter(|e| {
   184→                let name = e.file_name().to_string_lossy().to_string();
   185→                e.path().is_file() && glob_pattern.matches(&name)
   186→            })
   187→            .map(|e| e.path())
   188→            .collect();
   189→
   190→        results.extend(entries);
   191→    }
   192→
   193→    // Remove duplicates and sort
   194→    results.sort();
   195→    results.dedup();
   196→
   197→    if results.is_empty() {
   198→        let pattern_list = patterns.join(", ");
   199→        bail!(
   200→            "no tspec files found matching '{}' in {}",
   201→            pattern_list,
   202→            crate_dir.display()
   203→        );
   204→    }
   205→
   206→    Ok(results)
   207→}
