   209→/// Get binary path for a build with a spec
   210→pub fn get_binary_path(workspace: &Path, crate_name: &str, spec: &Spec, release: bool) -> PathBuf {
   211→    let is_release = release || spec.cargo.profile.as_ref() == Some(&Profile::Release);
   212→
   213→    let target = spec.cargo.target_triple.clone().or_else(|| {
   214→        spec.cargo
   215→            .target_json
   216→            .as_ref()
   217→            .and_then(|p| p.file_stem().map(|s| s.to_string_lossy().to_string()))
   218→    });
   219→
   220→    let profile_dir = if is_release { "release" } else { "debug" };
   221→
   222→    match target {
   223→        Some(t) => workspace
   224→            .join("target")
   225→            .join(t)
   226→            .join(profile_dir)
   227→            .join(crate_name),
   228→        None => workspace.join("target").join(profile_dir).join(crate_name),
   229→    }
   230→}
   231→
   232→/// Get binary path for a simple build (no spec)
   233→pub fn get_binary_path_simple(workspace: &Path, crate_name: &str, release: bool) -> PathBuf {
   234→    let profile_dir = if release { "release" } else { "debug" };
   235→    workspace.join("target").join(profile_dir).join(crate_name)
   236→}
