    25→/// Check if current directory is a package (has Cargo.toml with [package])
    26→fn current_package_name() -> Option<String> {
    27→    let cwd = std::env::current_dir().ok()?;
    28→    get_crate_name(&cwd).ok()
    29→}
    30→
    31→fn run() -> Result<ExitCode> {
    32→    let cli = Cli::parse();
    33→
    34→    match cli.command {
    35→        Commands::Build {
    36→            package,
    37→            all,
    38→            tspec,
    39→            release,
    40→            strip,
    41→            fail_fast,
    42→        } => {
    43→            // Resolve package: --all > -p PKG > cwd > all
    44→            let resolved = if all {
    45→                None
    46→            } else {
    47→                package.or_else(current_package_name)
    48→            };
    49→            match resolved {
    50→                None => {
    51→                    // Build all packages
    52→                    let workspace = WorkspaceInfo::discover()?;
    53→                    let results =
    54→                        build_all(&workspace, tspec.as_deref(), release, strip, fail_fast);
    55→                    return Ok(print_summary(&results));
    56→                }
    57→                Some(name) => {
    58→                    let result = build_crate(&name, tspec.as_deref(), release)?;
    59→                    if strip {
    60→                        strip_binary(&result.binary_path)?;
    61→                    }
    62→                }
    63→            }
    64→        }
    65→        Commands::Run {
    66→            package,
    67→            all,
    68→            tspec,
    69→            release,
    70→            strip,
    71→        } => {
    72→            // Resolve package: --all > -p PKG > cwd > all
    73→            let resolved = if all {
    74→                None
    75→            } else {
    76→                package.or_else(current_package_name)
    77→            };
    78→            match resolved {
    79→                None => {
    80→                    // Run all apps
    81→                    let workspace = WorkspaceInfo::discover()?;
    82→                    let results = run_all(&workspace, tspec.as_deref(), release, strip);
    83→                    return Ok(print_run_summary(&results));
    84→                }
    85→                Some(name) => {
    86→                    // Build, optionally strip, then run
    87→                    let result = build_crate(&name, tspec.as_deref(), release)?;
    88→                    if strip {
    89→                        strip_binary(&result.binary_path)?;
    90→                    }
    91→                    let exit_code = run_binary(&result.binary_path)?;
    92→                    std::process::exit(exit_code);
    93→                }
    94→            }
    95→        }
    96→        Commands::Test {
    97→            package,
    98→            all,
    99→            tspec,
   100→            release,
   101→            fail_fast,
   102→        } => {
   103→            // Resolve package: --all > -p PKG > cwd > all
   104→            let resolved = if all {
   105→                None
   106→            } else {
   107→                package.or_else(current_package_name)
   108→            };
   109→            match resolved {
