   137→            // TODO: implement
   138→        }
   139→        Commands::Incompat { package, spec } => {
   140→            println!("incompat add: package={package} spec={spec}");
   141→            // TODO: implement
   142→        }
   143→        Commands::Tspec { command } => match command {
   144→            TspecCommands::List { package, all } => {
