   158→            } => {
   159→                xt::ts_cmd::hash_tspec(package.as_deref(), all, tspec.as_deref())?;
   160→            }
   161→            TspecCommands::New {
   162→                name,
   163→                package,
   164→                from,
   165→            } => {
   166→                xt::ts_cmd::new_tspec(package.as_deref(), &name, from.as_deref())?;
